INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62426147', 62426147, 'analyze_legacy', 'Badan Nasional Penanggulangan Terorisme', 'central', 'Badan Nasional Penanggulangan Terorisme', 'Pekerjaan Sewa Mesin Fotokopi di Kantor BNPT', 'Barang', 'E-Purchasing', 'Jawa Barat, Bogor (Kab.)', 660000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, 'satu Paket', 'Ruang lingkup pekerjaan pengadaan sewa mesin fotokopi di Kantor BNPT sebanyak 16 (enam belas) unit yang ditempatkan di beberapa lokasi sebagai berikut: No Lokasi Penempatan Gedung Jumlah Unit 1 Ruang Tata Usaha Kepala Biwara - Lantai 1 1 unit 2 Ruang Kerja PLN Biwara - Lantai 1 1 unit 3 Ruang Tata Usaha Sekretariat Utama Biwara - Lantai 1 1 unit 4 Ruang Tata Usaha Kepala Biro Perencanaan, Hukum, dan Humas Biwara - Lantai 2 1 unit 5 Ruang Tata Usaha Deputi Bidang Pencegahan, Perlindungan, dan Deradikalisasi Biwara - Lantai 2 1 unit 6 Ruang Tata Usaha Biro Umum Baladika - Lantai 1 1 unit 7 Ruang Bagian Keuangan Baladika - Lantai 1 1 unit 8 Ruang Bagian Kepegawaian dan Organisasi Baladika - Lantai 2 1 unit 9 Koridor Nenggala - Lantai1 1 unit 10 Koridor Nenggala - Lantai 2 1 unit 11 Ruang Tata Usaha Deputi Bidang Penindakan dan Pembinaan Kemampuan Royal Sentul Park - Lantai 1 1 unit 12 Koridor Royal Sentul Park - Lantai 2 1 unit 13 Ruang Tata Usaha Kepala BNPT Gedung Kantor Wisma Mandiri - Lantai 4 1 unit 14 Ruang IK-Hub Gedung Kantor Plaza Hayam Wuruk - Lantai 16 1 unit 15 Ruang Tata Usaha Deputi Bidang Kerjasama Internasional Gedung Kantor Plaza Hayam Wuruk - Lantai 17 1 unit 16 Ruang Subbagian Rumah Bangunan Garasi dan 1 unit Tangga dan Layanan Pengadaan Total 16 Unit', 'A. Spesifikasi standar pelayanan yang diinginkan dari pekerjaan pengadaan sewa mesin fotokopi yang menjadi tugas penyedia adalah : 1. Penyedia harus memberikan mesin fotokopi yang baik dan siap dioperasikan tanpa kendala apapun sesuai dengan spesifikasi teknis; 2. Penyedia wajib menjamin dan menyediakan bahan pakai berupa toner, drum dengan kualitas yang baik; 3. Penyedia wajib memberikan layanan pemeliharaan rutin bulanan terhadap seluruh mesin fotokopi; 4. Penyedia harus menyediakan pelayanan hotline yang bisa dihubungi sewaktu-waktu saat terjadi kendala; 5. Penyedia wajib memberikan layanan pemeliharaan seperti penggantian sparepart mesin fotokopi (apabila terjadi kerusakan ringan) selama masa kontrak, dan menyiapkan 1(satu) toner catridge toner color (berwarna) cadangan pada setiap unit untuk menjaga ketersediaan bahan pakai; 6. Penyedia harus melakukan penggantian unit apabila terjadi kerusakan berat pada mesin fotokopi existing; 7. Penyedia memberikan laporan bulanan atas pemeliharaan rutin perangkat mesin fotokopi untuk evaluasi kinerja dan kebutuhan. B. Spesifikasi mesin yang diinginkan dari pekerjaan pengadaan sewa mesin fotokopi diantaranya sebagai berikut: 1. Main Unit. COPY SPEED : Kecepatan min 45 lembar per menit; COPY RESOLUTION : 1200 dpi x 600 dpi; MAGNIFICATION : Pengecilan dan pembesaran 25% s.d. 400 %; DUPLEXING : Otomatis (DADF); POWER CONSUMPTION : Daya listrik maksimal 1.500 watt; NUMBER OF CASSETTE : 4 baki/laci kertas; MEMORY : 1.25 GB RAM, Maksimum 1.75 GB RAM; HARD DISK : 160 GB. 2. ADF (Automatic Document Feeder) ACCEPTABLE ORIGINALS : Ukuran A5 – A3; ORIGINAL CAPACITY : Kapasitas 100 lembar. 3. FINISHER UNIT AUTO OFFSET-COLLATING : Otomatis mensortir hasil copy set per set; AUTO MULTI-STAPPLE : Otomatis menstaples hasil copy. 4. PRINT PRINTING RESOLUTION : 1200 dpi x 1200 dpi. 5. SCAN WARNA SCANNING RESOLUTION : 600 dpi x 600 dpi. 6. Scan Format : TIFF, JPEG*, PDF (Compact Searchable, Encrypted, Digital Signature) 7. SEND METHODS SEND RESOLUTION : 600 dpi x 600 dpi. 8. USB Media Support Print and scan pada media USB/Flashdisk. 9. Support jaringan LAN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 490567);
