INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62426622', 62426622, 'analyze_legacy', 'Badan Nasional Penanggulangan Terorisme', 'central', 'Badan Nasional Penanggulangan Terorisme', 'Pekerjaan Sewa Kendaraan Dinas Kepala BNPT dan Pejabat Eselon I', 'Barang', 'E-Purchasing', 'Jawa Barat, Bogor (Kab.)', 3510000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, 'satu Paket', 'Ruang Lingkup pekerjaan pengadaan sewa kendaraan dinas Kepala BNPT dan Pejabat Eselon I tahun 2026 adalah di antaranya: 1. Penyediaan kendaraan dinas melalui mekanisme sewa; 2. Penyediaan kendaraan bagi: a. Kepala BNPT berupa 1 (satu) unit Toyota Land Cruiser, tipe VX-R, tahun pembuatan minimal tahun 2023; b. Pejabat Eselon I berupa 4 (empat) unit Toyota Camry, tipe 2.5 V, tahun pembuatan minimal tahun 2023. 3. Pemeliharaan kendaraan selama masa sewa, termasuk: a. Servis berkala; b. Perbaikan kerusakan; c. Penggantian suku cadang; d. Asuransi kendaraan. 4. Penyediaan kendaraan pengganti apabila kendaraan utama mengalami gangguan operasional. E. PENDEKATAN DAN METODOLOGI Pendekatan dan metodologi dalam pengadaan sewa kendaraan dinas Kepala BNPT dan Pejabat Eselon I tahun 2026 mencakup hal-hal sebagai berikut : a. Pengumpulan data kebutuhan kendaraan; b. Perencaaan pengadaan; c. Proses pengadaan dilaksanakan dengan metode sewa sesuai harga yang tercantum di e-katalog; d. Pendataan dan distribus kendaraan.', '1 Toyota Land Cruiser Tipe VX-R 2 Toyota Toyota Camry Type 2.5 V', 3510000000, 'absurd', 'Pengadaan sewa kendaraan dinas untuk pimpinan dengan spesifikasi sangat premium, termasuk Toyota Land Cruiser VX-R dan beberapa Toyota Camry keluaran baru, menimbulkan indikasi kuat penggunaan anggaran yang berlebihan dan berpotensi memicu kecemburuan sosial. Untuk kebutuhan dinas, pilihan kendaraan mewah seperti ini tampak tidak proporsional terhadap prinsip efisiensi belanja publik.', NULL, NULL, 4, 1, 1, 1, 1, 493019);
