INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65459649', 65459649, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN KENAVIGASIAN PUSAT', 'Penyelenggaraan NDC LRIT INDONESIA', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 697250000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Sesuai dengan Peraturan Menteri Perhubungan Nomor PM 4 tahun 2023 tentang Penyelenggaraan Telekomunikasi-Pelayaran dan Pelayanan Tata Kelola Lalu Lintas Kapal Di Perairan Indonesia telah diatur terkait penyelenggaraan Long Range Identification and Tracking of Ship (LRIT) yang identifikasi dan penjejakan kapal jarak jauh yang melibatkan kapal yang masuk dan keluar wilayah Perairan Indonesia untuk menyediakan informasi data kapal, posisi dan penjejakan kepada Menteri melalui peralatan Long Range Identification and Tracking of Ship (LRIT). Penyelenggaraan tersebut dilaksanakan melalui National Data Center (NDC) Indonesia yang dilaksanakan oleh Direktorat Jenderal Perhubungan Laut.', 'Memperkuat keaktifan Indonesia dalam hal ini Direktorat Jenderal Perhubungan Laut selaku anggota Advisory Committee untuk penyelenggaraan Long Range Identification Tracking of Ship (LRIT) sesuai dengan Peraturan Menteri Perhubungan Nomor PM 4 tahun 2023 Tentang Penyelenggaraan Telekomunikasi-Pelayaran Dan Pelayanan Tata Kelola Lalu Lintas Kapal Di Perairan Indonesia dan peraturan Internasional; Meningkatnya PNBP (Pendapatan Negara Bukan Pajak) dalam bidang kegiatan Long Range Identification Tracking of Ship (LRIT) setelah dilakukannya Edukasi Registrasi LRIT bagi setiap perusahaan pelayaran yang ada di Indonesia; Evaluasi antara Direktorat Kenavigasian dengan pihak penyelenggara Long Range Identification Tracking of Ship (LRIT) memberikan sinergi dalam meningkatkan pelayanan LRIT di Indonesia serta sinkronnnya data layanan; Delegasi Indonesia dapat mengikuti perkembangan isu global maupaun Informasi dan Teknologi Satelit dalam melaksanakan tugas Penyelanggaraan Telekomunikasi Pelayaran yang diperuntukkan dalam Keselamatan Pelayaran melalui untuk penyelenggaraan Long Range Identification Tracking Of Ship (LRIT);dan Membuka kesempatan dalam membangun jaringan koordinasi internasional untuk kemungkinan kerjasama antara negara dan lembaga dalam penyelenggaran Long Range Identification Tracking of Ship (LRIT).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 493392);
