INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62426421', 62426421, 'analyze_legacy', 'Badan Nasional Penanggulangan Terorisme', 'central', 'Badan Nasional Penanggulangan Terorisme', 'Pekerjaan Sewa Tanaman Hias dan Bunga di Lingkungan Kantor BNPT', 'Barang', 'E-Purchasing', 'Jawa Barat, Bogor (Kab.)', 370000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, 'satu Paket', 'Ruang lingkup pekerjaan meliputi: 1. Penyediaan tanaman hias dan bunga dengan pot yang mendukung sesuai kebutuhan; 2. Penataan dan peletakan tanaman hias dan bunga pada titik lokasi; 3. Pemeliharaan dan perawatan tanaman; 4. Pemberian pupuk/obat tanaman; 5. Penggantian tanaman apabila tanaman mati/layu/rusak; 6. Jenis Tanaman yang harus disediakan oleh penyedia adalah sebagai berikut: Lokasi penempatan tanaman hias dan bunga berdasarkan hasil survei kebutuhan, meliputi: No Lokasi Sasaran Jumlah Kebutuhan Tanaman Hias Jumlah Kebutuhan Bunga 1 Gedung Biwara : a.Lantai 1 10 Pot 2 pot b.Lantai 2 9 Pot 2 Gedung Baladika : a. Lantai 1 13 Pot b. Lantai 2 8 Pot 3 Gedung Nenggala : a. Lantai 1 6 Pot b. Lantai 2 6 Pot 4 Gedung Royal Sentul Park a. Lantai 1 4 Pot b. Lantai 2 4 Pot 5 Gedung Wisma Mandiri : a. Lantai 4 8 Pot 2 Pot 6 Gedung Hayam Wuruk : a. Lantai 16 6 Pot b. Lantai 17 6 Pot 7 Museum Penanggulangan Terorisme Adhi Pradana a. Lantai 1 8 Pot b. Lantai 2 4 Pot 8 Klinik Pratama 2 Pot Total 94 Pot 4 Pot', '1. Jenis Tanaman A. Jenis Tanaman: - Tanaman palem kuning; - Tanaman cemara norflok; - Tanaman palem waregu; - Tanaman sansivera; - Tanaman pillodendron; - Tanaman palem kipas; - Tanaman aglonema; - Tanaman anthurium jemani; - Tanaman dracaena bambu; - Tanaman aglonema; - Tanaman walisongo; - Tanaman karet kebo; - Tanaman ceriman. 2. Kondisi Tanaman Hias & Bunga Tanaman yang disediakan harus memenuhi ketentuan: - Tanaman sehat, segar, tidak layu, tidak terserang hama/penyakit; - Daun bersih, tidak menguning, atau kering; - Media tanam bermutu baik dan tidak berbau; - Akar kuat dan tanaman berdiri stabil dalam pot; - Tinggi tanaman 50 s.d 80 cm; - Penampilan estetis dan proporsional. Kondisi bunga: - Jenis bunga : Anggrek Premium (Grade A); - Warna bunga : putih/ungu/batik - Arrangement : susunan formal elegan suitable; - Jumlah tangkai 5 tangkat per pot; - Kondisi bunga mekar sempurna ≥ 80%, tidak layu, tidak rusak; - Daun tebal dan tidak menguning; - Akar sehat, tidak busuk, dan tidak terserang jamur. 3. Pot dan Perlengkapan - Pot dapat berbahan fiber, keramik, atau plastik berkualitas tinggi; - Ukuran pot menyesuaikan ukuran tanaman; - Warna pot netral/elegan; - Pot dalam plastik diameter 35 cm; - Pot luar ceramic atau gerabah diameter 40 cm dan tinggi 70 cm; - Dilengkapi alas pot dan aksesori dekoratif bila diperlukan. 4. Layanan Pemeliharaan Rutin (Maintenance) Penyedia wajib melakukan pemeliharaan meliputi: - Penyiraman dan pemberian nutrisi (min.2x dalam 1 bulan atau sesuai kebutuhan jenis tanaman); - Perawatan estetika visual daun dan kebersihan pot; - Pengendalian hama; - Pemangkasan jika diperlukan; - Penggantian tanaman yang rusak, layu, atau mati tanpa biaya tambahan. 5. Standar Kualitas Layanan - Respon maksimal 1×24 jam apabila terdapat keluhan atau kerusakan; - Tenaga teknis pemeliharaan berpengalaman di bidang tanaman hias indoor; - Dokumentasi laporan pergantian tanaman dan pemeliharaan (bulanan).', 185000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 493800);
