INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65548806', 65548806, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Individual: Penyusunan Profil Dan Rekomendasi Strategi Pengembangan Kapasitas SDM Pemerintah Daerah Berdasarkan Pendekatan Asimetris Kegiatan Koordinasi Strategis Kebijakan Pembangunan Lingkup Penguatan Kapasitas Sumber Daya Manusia Pemerintah Daerah Direktorat Pemerintahan, Keuangan Daerah, Dan Transfer Ke Daerah', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 142560000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Menyusun kerangka analisis pengembangan kapasitas SDM Pemerintah Daerah berbasis pendekatan asimetris sesuai karakteristik dan kapasitas daerah. 2. Melakukan pemetaan pemangku kepentingan di tingkat pusat dan daerah serta merumuskan kebutuhan koordinasi lintas aktor dalam penguatan kapasitas SDM Pemerintah Daerah. 3. Melakukan pengumpulan, pengolahan, dan analisis data terkait profil, distribusi, dan kondisi SDM ASN di daerah sebagai dasar penyusunan basis data dan profil SDM Pemerintahan Daerah 4. Menyusun profil dan tipologi kapasitas SDM Pemerintah Daerah berdasarkan pendekatan asimetris, termasuk pengelompokan daerah sesuai tingkat kapasitas dan kebutuhan pengembangan kompetensi, 5. Mengidentifikasi isu strategis penguatan kapasitas SDM Pemerintah Daerah serta menyusun rekomendasi kebijakan dan strategi pengembangan SDM berbasis kebutuhan dan kapasitas daerah juga sebagai masukan untuk revisi UU 23/2014 tentang Pemerintahan Daerah;', '1. Merupakan Tenaga Ahli dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan status valid Konfirmasi Status Wajib Pajak (KSWP) 3. Memiliki pendidikan minimal Strata Satu (S1) di bidang Pengembangan Wilayah/ Perencanaan Wilayah dan Kota/ Manajemen Kebijakan Publik yang dibuktikan dengan ijazah; 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 5 (lima) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sub kontrak yang dibuktikan dengan surat kontrak/referensi pekerjaan yang pernah dilakukan; 5. Memiliki pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan), dibidang perencanaan dan/atau evaluasi kebijakan pemerintah utamanya mengenai isu kebijakan desentralisasi dan otonomi daerah minimal 2 (dua) tahun dalam kurun waktu 5 (lima) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak yang dibuktikan dengan surat kontrak/referensi pekerjaan yang pernah dilakukan; 6. Memiliki pengalaman pekerjaan dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% nilai total HPS;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 493891);
