INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65465145', 65465145, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Pemeliharaan Kendaraan Dinas Fungsional Jemputan Sewa dan Pemeliharaan Kendaraan Dinas Roda 4 Eselon I Sewa Untuk Kegiatan Pemeliharaan Kendaraan Dinas Operasional Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 101000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PAKET', 'Pekerjaan ini merupakan penyediaan layanan pemeliharaan kendaraan dinas sewa yang terdiri atas Kendaraan Dinas Fungsional Jemputan sebanyak 3 (tiga) unit dan Kendaraan Dinas Roda 4 Eselon I sebanyak 1 (satu) unit untuk jangka waktu 1 (satu) Tahun Anggaran dalam rangka mendukung kegiatan Pemeliharaan Kendaraan Dinas Operasional Kantor pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026. Kegiatan ini bertujuan untuk memastikan kendaraan dinas sewa tetap dalam kondisi optimal, aman, dan layak jalan melalui pelaksanaan pemeliharaan rutin dan berkala, termasuk servis berkala, penggantian suku cadang habis pakai, pemeriksaan sistem kendaraan, serta perbaikan apabila terjadi kerusakan selama masa penggunaan, sehingga kendaraan senantiasa siap digunakan untuk menunjang mobilitas dan kegiatan kedinasan.', 'Spesifikasi teknis pekerjaan ini adalah penyediaan layanan pemeliharaan kendaraan dinas sewa yang terdiri atas 3 (tiga) unit Kendaraan Dinas Fungsional Jemputan dan 1 (satu) unit Kendaraan Dinas Roda 4 Eselon I selama 1 (satu) Tahun Anggaran, yang mencakup pemeliharaan rutin dan berkala sesuai standar pabrikan, termasuk servis berkala, penggantian oli dan filter, penggantian suku cadang habis pakai, pemeriksaan sistem mesin, kelistrikan, sistem pengereman, kaki-kaki, dan komponen pendukung lainnya, serta perbaikan atas kerusakan yang terjadi selama masa sewa. Layanan pemeliharaan dilaksanakan untuk memastikan kendaraan dalam kondisi laik jalan, aman, dan siap operasional, dengan penggunaan suku cadang yang sesuai standar serta didukung tenaga teknis yang kompeten. Penyedia wajib menjamin kendaraan tetap dalam kondisi baik selama masa kontrak dan melakukan penanganan perbaikan secara tepat waktu apabila terjadi gangguan operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 494465);
