INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63042181', 63042181, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL PENANGGULANGAN PENYAKIT', 'Penayangan TBC melalui ILM', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 1800000000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 6, PT, @ 300000000 )', '1. Penayangan TBC melalui ILM ( 6, PT, @ 300000000 );', '• Penayangan ILM TBC (TV spot) durasi 30 detik di media TV kereta api (commuter line/KRL) Jabodetabek • Total penayangan spot per hari: 20 spot (30 detik) selama 60 hari • Penayangan spot per harinya adalah setiap hari (looping) • Jam operasional kereta adalah pada jam 05.00 – 22.00 WIB • Penayangan per hari 20 spot (durasi 30 detik) di bagi menjadi 2 spot yaitu 10 spot pada jam prime time pagi dan prime time sore serta 10 spot pada regular time pagi dan regular malam, kecuali pada hari Sabtu dan Minggu. • Prime time pagi adalah mulai pukul 05.00- 08.00 WIB dan Prime time sore adalah mulai pukul 16.00-18.00 WIB • Regular time pagi adalah pukul 09.00-15.00 WIB dan Regular time malam adalah pukul 20.00-22.00 WIB. • Media plan untuk penayangan akan diberikan oleh pihak penyedia sebelum penayangan. • Pada saat pelaksaan penayangan, user akan diberikan timeline atau jadwal penayangan spot iklan per hari setiap harinya oleh pihak penyedia • Laporan akhir hasil penayangan (softfile dan hardfile) dan dokumentasi (foto dan video)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 494639);
