INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63041950', 63041950, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK', 'Belanja Pengelolaan Layanan Teknologi Informasi dan Komunikasi (Technical Support B)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 111925000, 'January 2026', 'APBD', 1, 1, '11 Bulan', '1) Melakukan instalasi dan peningkatan sistem yang dikelola UP Layanan TIK diantaranya: Gitlab, Email (enterprise, community dan Lab), Aplikasi Layanan TIK Diskominfotik (servicedesk), Spesimen, StorageDKI, Esign Client; 2) Eskalasi ke senior engineer atau principal jika ada masalah yang tidak dapat diselesaikan; 3) Melakukan Tugas Administrasi IT seperti pembuatan dokumen teknis TIK pada Unit Pengelola layanan TIK ke internal atau eksternal; 4) Dokumentasikan pengetahuan teknis dalam database pengetahuan misal: platform media penyimpanan BookStack atau lainnya; 5) Mengikuti prosedur standar untuk menyelesaikan masalah dengan menghubungkannya ke PD/UKPD/Internal terkait; 6) Menyelesaikan masalah yang berkaitan dengan Sistem/aplikasi yang dikelola UP Layanan TIK; 7) Menginstal dan mengkonfigurasi sistem operasi, aplikasi komputer dan Server pada sistem/aplikasi yang dikelola UP Layanan TIK; 8) Menganalisis, memecahkan masalah teknis dan melakukan penanganan teknis terhadap masalah meliputi perbaikan OS dan perangkat lunak, diagnosa lengkap, melakukan remote ke server untuk penanganan lebih dalam pada sistem/aplikasi yang dikelola UP Layanan TIK 9) Menerima, melakukan analisa dan memecahkan masalah serta memberikan masukan atau rekomendasi terhadap aduan Teknologi Informasi dan Komunikasi yang dieskalasi oleh Helpdesk. 10) Memonitoring masalah sistem/aplikasi pada infrastruktur yang dikelola UP Layanan TIK sesuai dengan jadwal yang disepakati hingga masalah terselesaikan; 11) Membuat laporan bulanan;', '• S1 Teknik Informatika • Pengalaman sebagai Technical Support paling kurang 1 (satu) pekerjaan dalam kurun waktu 1 (Satu) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak • Memiliki sertifikat pelatihan antara lain : o Linux o Virtual Machine o Pengelolaan Server Email (zimbra/Carbonio) o Python, PHP, HTML, CSS, Javascript. o Webservice/API o Database Oracle/MySql o GIT o Docker', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 498188);
